namespace sv_cb84fbf3dd374bc1bbae6fd74422b85c.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

public record ThemeInfo(Theme Theme = Theme.Light, string AccentColor = "#0d6efd");

using Microsoft.AspNetCore.Components;

namespace sv_cb84fbf3dd374bc1bbae6fd74422b85c.Services;

/// <summary>
/// Scoped service (per-circuit on Server) that owns theme state and
/// pushes changes through CascadingValueSource so every subscriber
/// re-renders — including components in the static layout.
/// </summary>
public class ThemeService
{
    private readonly CascadingValueSource<ThemeInfo> _source;

    public ThemeService()
    {
        Current = new ThemeInfo();
        _source = new CascadingValueSource<ThemeInfo>(Current, isFixed: false);
    }

    public ThemeInfo Current { get; private set; }

    /// <summary>
    /// Exposed so DI can register it with AddCascadingValue.
    /// </summary>
    public CascadingValueSource<ThemeInfo> Source => _source;

    public async Task SetThemeAsync(Theme theme)
    {
        Current = Current with { Theme = theme };
        await _source.NotifyChangedAsync(Current);
    }

    public async Task SetAccentColorAsync(string accentColor)
    {
        Current = Current with { AccentColor = accentColor };
        await _source.NotifyChangedAsync(Current);
    }

    public async Task SetAllAsync(Theme theme, string accentColor)
    {
        Current = new ThemeInfo(theme, accentColor);
        await _source.NotifyChangedAsync(Current);
    }
}

