@* Reads theme via CascadingParameter — works even in the static layout
   because the value comes from CascadingValueSource in DI, not from a
   <CascadingValue> component in the render tree. *@

<span class="badge" style="background-color: @(Theme?.AccentColor ?? "#0d6efd")">
    @(Theme?.Theme.ToString() ?? "Light")
</span>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="mb-3">
    <label class="form-label fw-bold">Theme</label>
    <div class="btn-group d-block" role="group">
        @foreach (var t in Enum.GetValues<Theme>())
        {
            var isActive = t == _selectedTheme;
            <button type="button"
                    class="btn @(isActive ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => SelectTheme(t)">
                @t
            </button>
        }
    </div>
</div>

<div class="mb-3">
    <label class="form-label fw-bold" for="accent-color">Accent Color</label>
    <input id="accent-color" type="color" class="form-control form-control-color"
           value="@_accentColor"
           @onchange="OnAccentChanged" />
</div>

<div class="mt-4">
    <button class="btn btn-success" @onclick="Save">Save Preferences</button>
    @if (_saved)
    {
        <span class="text-success ms-2">✓ Saved</span>
    }
</div>

<div class="mt-4 p-3 rounded" style="background-color: @_accentColor; color: white;">
    Preview: accent color applied
</div>

@code {
    private Theme _selectedTheme;
    private string _accentColor = "#0d6efd";
    private bool _saved;

    protected override void OnInitialized()
    {
        _selectedTheme = ThemeService.Current.Theme;
        _accentColor = ThemeService.Current.AccentColor;
    }

    private void SelectTheme(Theme theme)
    {
        _selectedTheme = theme;
        _saved = false;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        _accentColor = e.Value?.ToString() ?? "#0d6efd";
        _saved = false;
    }

    private async Task Save()
    {
        await ThemeService.SetAllAsync(_selectedTheme, _accentColor);
        _saved = true;
    }
}

